package com.agacostays.payroll.controller; import com.agacostays.payroll.dto.request.SalaryStructureRequest;import com.agacostays.payroll.dto.response.*;import com.agacostays.payroll.security.CurrentUserProvider;import com.agacostays.payroll.service.SalaryStructureService;import jakarta.validation.Valid;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/manager/payroll/salary-structures") public class SalaryStructureController{final SalaryStructureService s;final CurrentUserProvider c;public SalaryStructureController(SalaryStructureService s,CurrentUserProvider c){this.s=s;this.c=c;}@PostMapping public ResponseEntity<ApiResponse<SalaryStructureResponse>> create(@Valid @RequestBody SalaryStructureRequest r){return ResponseEntity.ok(ApiResponse.ok("Salary structure created",s.create(r,c.userId())));}@GetMapping public ResponseEntity<ApiResponse<java.util.List<SalaryStructureResponse>>> list(){return ResponseEntity.ok(ApiResponse.ok("Salary structures fetched",s.list()));}@GetMapping("/role/{role}") public ResponseEntity<ApiResponse<SalaryStructureResponse>> role(@PathVariable String role){return ResponseEntity.ok(ApiResponse.ok("Salary structure fetched",s.byRole(role)));}@PutMapping("/{id}") public ResponseEntity<ApiResponse<SalaryStructureResponse>> update(@PathVariable Long id,@Valid @RequestBody SalaryStructureRequest r){return ResponseEntity.ok(ApiResponse.ok("Salary structure updated",s.update(id,r,c.userId())));}@DeleteMapping("/{id}") public ResponseEntity<ApiResponse<Void>> delete(@PathVariable Long id){s.deactivate(id);return ResponseEntity.ok(ApiResponse.ok("Salary structure deactivated",null));}}
